    requireRule(c && s.progress.flags[c.completeFlag], "\u5148\u5B8C\u6210\u8FD9\u4E00\u5377\u3002");
    const f = "kit_chapter_" + id;
    requireRule(!s.progress.flags[f], "\u672C\u5377\u8865\u7ED9\u5DF2\u7ECF\u9886\u53D6\u3002");
    s.progress.flags[f] = true;
    grant(s, { items: { vital_pill: 1, material_choice: 1 } }, d);
